{{ (function(){
  var rows = (SelectQuery.data || []);
  var sarakkeet = [
    ["uusi","Uusi"], ["tarjous_lahetetty","Tarjous lähetetty"], ["tilaus_vastaanotettu","Tilaus vastaanotettu"],
    ["suunnittelussa","Suunnittelussa"], ["tuotannossa","Tuotannossa"], ["odottaa_asennusta","Odottaa asennusta"],
    ["valmis","Valmis"], ["toimitettu","Toimitettu"], ["laskutettu","Laskutettu"]
  ];
  var varit = { 0: "#B4232A", 1: "#DC2626", 2: "#B45309", 3: "#1D4ED8" };
  var esc = function(s){ return String(s == null ? "" : s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); };
  var jono = rows.slice().sort(function(a,b){
    var ta = (a.kiire_taso == null ? 9 : Number(a.kiire_taso)), tb = (b.kiire_taso == null ? 9 : Number(b.kiire_taso));
    if (ta !== tb) { return ta - tb; }
    return Number(b.kiire_odotus || 0) - Number(a.kiire_odotus || 0);
  });
  var html = "";
  for (var i = 0; i < sarakkeet.length; i++) {
    var koodi = sarakkeet[i][0], nimi = sarakkeet[i][1];
    var omat = jono.filter(function(r){ return r.status === koodi; });
    var kortit = omat.map(function(r){
      var vari = varit[r.kiire_taso] || "#9CA3AF";
      var merkit = [];
      if (r.uusi_viesti_suljettuun) { merkit.push("Uusi viesti"); }
      else if (r.odottaa_meilta) { merkit.push("Odottaa meitä"); }
      if (r.valmistumispaiva) { merkit.push("Valmis " + moment(r.valmistumispaiva).format("D.M.")); }
      if (r.omistaja && r.omistaja !== "Ei vastuuhenkilöä") { merkit.push(r.omistaja); }
      var m = merkit.length ? "<div class=\"m\">" + esc(merkit.join(" · ")) + "</div>" : "";
      return "<div class=\"c\" style=\"border-left-color:" + vari + "\" data-id=\"" + esc(r.id) + "\">"
           + "<div class=\"t\">" + esc(r.tp_numero) + "</div>"
           + "<div class=\"y\">" + esc(r.yritys || r.asiakas || "") + "</div>"
           + "<div class=\"a\">" + esc(r.aihe || "") + "</div>" + m + "</div>";
    }).join("");
    if (!kortit) { kortit = "<div class=\"e\">–</div>"; }
    html += "<div class=\"col\"><div class=\"h\"><span>" + nimi + "</span><span class=\"n\">" + omat.length + "</span></div><div class=\"list\">" + kortit + "</div></div>";
  }
  var css = "html,body{height:100%;margin:0;overflow:hidden}body{font-family:-apple-system,Segoe UI,Roboto,Helvetica,sans-serif;font-size:12px;color:#1f2937;background:transparent}.w{display:flex;gap:8px;padding:2px;height:100%;box-sizing:border-box;overflow-x:auto;overflow-y:hidden}.col{flex:0 0 236px;display:flex;flex-direction:column;background:#f3f4f6;border-radius:8px;padding:6px;box-sizing:border-box;height:100%;overflow:hidden}.h{font-weight:600;font-size:12px;color:#374151;padding:2px 4px 6px;display:flex;justify-content:space-between;align-items:baseline;flex:0 0 auto}.n{color:#6b7280;font-weight:600}.list{overflow-y:auto;flex:1 1 auto;min-height:0}.c{background:#fff;border:1px solid #e5e7eb;border-left:4px solid #9CA3AF;border-radius:6px;padding:6px 8px;margin-bottom:6px;cursor:pointer}.c:hover{border-color:#9ca3af;background:#f9fafb}.t{font-weight:600;font-size:12px}.y{color:#374151;font-size:11px;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.a{color:#6b7280;font-size:11px;margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.m{font-size:10px;color:#6b7280;margin-top:4px}.e{color:#c7cbd1;text-align:center;padding:10px 0;font-size:11px}";
  var js = "document.addEventListener(\"click\",function(e){var n=e.target.closest(\"[data-id]\");if(n){parent.postMessage(\"tyo:\"+n.getAttribute(\"data-id\"),\"*\");}});";
  return "<html><head><meta charset=\"utf-8\"><style>" + css + "</style></head><body><div class=\"w\">" + html + "</div><script>" + js + "<\/script></body></html>";
})() }}
